def solve(g):
    h=len(g); w=len(g[0])
    centers={}; diamonds=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,3): centers[(r,c)]=g[r][c]
            if (g[r][c]==0 and 0<r<h-1 and 0<c<w-1 and g[r-1][c]==3 and g[r+1][c]==3
                and g[r][c-1]==3 and g[r][c+1]==3):
                diamonds.append((r,c))
    cols={c:(v,r) for (r,c),v in centers.items()}
    rows={r:(v,c) for (r,c),v in centers.items()}
    res=[row[:] for row in g]
    def ray(r,c,dr,dc,color):
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            if g[rr][cc]==3:
                if (rr,cc) in [(r-dr,c-dc)]:  # own frame -> pass through
                    pass
                else:
                    return
            rr+=dr; cc+=dc
        # paint
    # simpler: paint each ray cell unless original 3
    painted={}
    for (r,c),v in centers.items():
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if g[rr][cc]==3 and (rr,cc)!= (r+dr- dr, c+dc-dc) and not ((rr,cc) in [(r-dr,c-dc),(r+0,c+0)]):
                    pass
                if g[rr][cc]==3 and (rr,cc) not in [(r-dr,c-dc)]:
                    break
                painted[(rr,cc)]=('col' if dc==0 else 'row', v)
                rr+=dr; cc+=dc
    # column rays override row rays
    cell={}
    for (r,c),(kind,v) in painted.items():
        if (r,c) not in cell or (kind=='col' and cell[(r,c)][0]=='row'):
            cell[(r,c)]=(kind,v)
    for (r,c),(kind,v) in cell.items():
        if g[r][c]!=3: res[r][c]=v
    for (dr_,dc_) in diamonds:
        for r in range(h):
            if g[r][dc_]!=3: res[r][dc_]=0
    return res

