def solve(g, shadow=True):
    h=len(g); w=len(g[0])
    centers={}; diamonds=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,3): centers[(r,c)]=g[r][c]
            if (g[r][c]==0 and 0<r<h-1 and 0<c<w-1 and g[r-1][c]==3 and g[r+1][c]==3
                and g[r][c-1]==3 and g[r][c+1]==3):
                diamonds.append((r,c))
    own={}
    for (r,c) in centers:
        own[(r,c)]=True
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): own[(r+dr,c+dc)]=True
    marks={}  # (r,c) -> (priority, color); priority col=1,row=0
    for (r,c),v in centers.items():
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if g[rr][cc]==3 and (rr,cc) not in own:
                    break
                pri = 1 if dc==0 else 0
                if (rr,cc) not in marks or pri>marks[(rr,cc)][0]:
                    marks[(rr,cc)]=(pri,v)
                rr+=dr; cc+=dc
    res=[row[:] for row in g]
    for (r,c),(pri,v) in marks.items():
        if g[r][c]!=3: res[r][c]=v
    if shadow:
        for (dr_,dc_) in diamonds:
            for r in range(h):
                if g[r][dc_]!=3: res[r][dc_]=0
    return res

